/* Local offline scripts. No CDN. Navbar toggle and alert close only. */
document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('[data-bs-toggle="collapse"]').forEach(function (button) {
        button.addEventListener('click', function () {
            var selector = button.getAttribute('data-bs-target');
            var target = selector ? document.querySelector(selector) : null;
            if (!target) {
                return;
            }
            var open = target.classList.toggle('show');
            button.setAttribute('aria-expanded', open ? 'true' : 'false');
        });
    });

    document.querySelectorAll('[data-bs-dismiss="alert"]').forEach(function (button) {
        button.addEventListener('click', function () {
            var alert = button.closest('.alert');
            if (alert) {
                alert.remove();
            }
        });
    });
});
